UPDATE order_main
status = #{status}, pay_status = #{payStatus}, pay_method = #{payMethod}, checkout_time = #{checkoutTime}, cancel_reason = #{cancelReason}, cancel_time = #{cancelTime}, rejection_reason = #{rejectionReason}, delivery_time = #{deliveryTime},
