mapper.select:
SELECT

FROM order_main


        AND member_id = #{memberId}


        AND number LIKE CONCAT('%', #{number}, '%')


        AND phone LIKE CONCAT('%', #{phone}, '%')


        AND status = #{status}


        AND order_time >= #{beginTime}


        AND order_time <= #{endTime}


ORDER BY order_time DESC, id DESC

mapper.update:
UPDATE order_main
status = #{order.status}, pay_status = #{order.payStatus}, pay_method = #{order.payMethod}, checkout_time = #{order.checkoutTime}, cancel_reason = #{order.cancelReason}, cancel_time = #{order.cancelTime}, rejection_reason = #{order.rejectionReason}, delivery_time = #{order.deliveryTime},
WHERE id = #{order.id} AND status = #{fromStatus}

UPDATE order_main
SET status = #{toStatus},
    cancel_reason = #{reason},
    cancel_time = #{cancelTime}
WHERE status = #{fromStatus}
  AND order_time < #{deadline}

mapper.select:
SELECT oi.name AS name, SUM(oi.number) AS number FROM order_item oi INNER JOIN order_main om ON om.id = oi.order_id WHERE om.status = 5
AND om.order_time >= #{begin}
AND om.order_time <= #{end}
GROUP BY oi.name ORDER BY SUM(oi.number) DESC LIMIT 10
